def read_csv(path):
    with open(path,encoding='utf-8-sig',newline='') as f: return list(csv.DictReader(f))
def write_csv(path, fieldnames, rows):
    with open(path,'w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fieldnames,extrasaction='ignore'); w.writeheader(); w.writerows(rows)
def template_fields(name):
    with open(RET/name,encoding='utf-8-sig',newline='') as f: return next(csv.reader(f))
def J(x): return json.dumps(x,ensure_ascii=False,separators=(',',':'))
def rid(prefix,*parts): return f"{prefix}-{hashlib.sha256('|'.join(map(str,parts)).encode()).hexdigest()[:20]}"

def norm_wave(v): return str(v)
base=read_csv(BASE)
by_id={r['question_implementation_id']:r for r in base}
by_key={(r['source_family'],norm_wave(r['wave']),r['source_variable_code']):r for r in base}

def row(fam,wave,code):
    k=(fam,str(wave),code)
    if k not in by_key: raise KeyError(k)
    return by_key[k]
def ids(fam,wave,codes): return [row(fam,wave,c)['question_implementation_id'] for c in codes]
def texts(fam,wave,codes): return [row(fam,wave,c)['exact_question_text'] for c in codes]

# Governed p2xsafe IDs where present in R10A spine; absence is preserved as absence.
selected_ids=set(r['question_implementation_id'] for r in base)
sem_by_id={}
if SPINE.exists():
    with gzip.open(SPINE,'rt',encoding='utf-8-sig',newline='') as f:
        rd=csv.DictReader(f)
        for r in rd:
            iid=r.get('question_implementation_id','')
            if iid in selected_ids:
                sid=(r.get('sem__audit_unit_id') or '').strip()
                if sid.startswith('p2xsafe__'): sem_by_id[iid]=sid

def sems(member_ids):
    out=[]
    for iid in member_ids:
        s=sem_by_id.get(iid)
        if s and s not in out: out.append(s)
    return out

# Compact, exact source provenance objects.
def prov(doc,page,code,excerpt):
    return {'document':doc,'page':page,'source_variable_code':code,'exact_source_excerpt':excerpt}

