# Relation constructors.
pos=[]
def add_pos(fam,wave,norm_codes,praxis_codes,subtype,praxis_kind,norm_prop,praxis_prop,actor_scope,actor_basis,target_scope,target_basis,action_domain,action_basis,polarity,distance,bridge,condition,universe,provenance,basis,confidence='HIGH',grain='',t06_status='NO_STRICT_T06_DUPLICATION',overlap_rules=None):
    member_ids=ids(fam,wave,norm_codes+praxis_codes)
    rel=rid('T15W03',fam,wave,','.join(norm_codes),','.join(praxis_codes),subtype)
    roles=[]
    for c,i in zip(norm_codes,ids(fam,wave,norm_codes)):
        roles.append({'question_implementation_id':i,'source_variable_code':c,'relation_role':'RR_NORM','shore':'NORM'})
    for c,i in zip(praxis_codes,ids(fam,wave,praxis_codes)):
        roles.append({'question_implementation_id':i,'source_variable_code':c,'relation_role':'RR_PRACTICAL_REALIZATION','shore':'PRAXIS','praxis_shore_kind':praxis_kind})
    pos.append({
      'worker_relation_id':rel,'central_relation_id':'','authority_class':'WORKER_SOURCE_FIRST_PROPOSED_T15','rule_id':'S14-T15','relation_type':'NORM_PRACTICAL_REALIZATION','manifestation_subtype':subtype,
      'source_family':fam,'wave':str(wave),'active_source_wave_set_json':J([f'{fam}::{wave}']),'member_semantic_unit_ids_json':J(sems(member_ids)),'member_implementation_ids_json':J(member_ids),'role_assignments_json':J(roles),
      'common_proposition_or_target':target_scope,'norm_proposition':norm_prop,'praxis_proposition':praxis_prop,'praxis_shore_kind':praxis_kind,'actor_scope':actor_scope,'actor_alignment_basis':actor_basis,
      'target_scope':target_scope,'target_alignment_basis':target_basis,'action_domain':action_domain,'action_alignment_basis':action_basis,'relation_polarity':polarity,'realization_distance':distance,
      'bridge_basis_type':bridge,'bridge_basis_ids_json':J([]),'position_or_routing_condition':condition,'respondent_universe_intersection':universe,'source_provenance_json':J(provenance),
      'source_first_adjudication_basis':basis,'central_basis':'','confidence':confidence,'worker_origin':'T06W03','grain_note':grain,'t06_overlap_status':t06_status,
      'overlap_with_existing_s14_rule_json':J(overlap_rules or []),'successor_freeze_status':'WORKER_PROPOSED_NOT_FROZEN','successor_freeze_basis':'S14-T15 worker source-first reconstruction; requires central adjudication before successor freeze.'
    })
    return rel

